import { useRouter } from 'expo-router';
import * as Speech from 'expo-speech';
import { BookOpen, FileText, Sparkles, Square, Volume2 } from 'lucide-react-native';
import React, { useState } from 'react';
import { ActivityIndicator, ScrollView, StyleSheet, Text, TextInput, TouchableOpacity, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { BentoCard } from '../src/components/BentoCard';
import { Navbar } from '../src/components/Navbar';
import { ProgressCalendar } from '../src/components/ProgressCalendar';
import { useTheme } from '../src/context/ThemeContext';
import { analyzeContent, simplifyText } from '../src/services/gemini';

export default function HomeScreen() {
    const { theme, isDark } = useTheme();
    const router = useRouter();
    const [inputText, setInputText] = useState('');
    const [simplifiedText, setSimplifiedText] = useState('');
    const [analysis, setAnalysis] = useState('');
    const [loadingType, setLoadingType] = useState<'simplify' | 'analyze' | null>(null);
    const [isSpeaking, setIsSpeaking] = useState(false);
    const [error, setError] = useState('');

    const handleSimplify = async () => {
        if (!inputText.trim()) return;
        setLoadingType('simplify');
        setError('');

        try {
            const result = await simplifyText(inputText);
            setSimplifiedText(result.simplified);
        } catch (err: any) {
            setError(err.message);
        } finally {
            setLoadingType(null);
        }
    };

    const handleAnalyze = async () => {
        const textToAnalyze = simplifiedText || inputText;
        if (!textToAnalyze.trim()) return;
        setLoadingType('analyze');
        setError('');

        try {
            const result = await analyzeContent(textToAnalyze);
            setAnalysis(result.analysis);
        } catch (err: any) {
            setError(err.message);
        } finally {
            setLoadingType(null);
        }
    };

    const handleReadAloud = async () => {
        const textToRead = simplifiedText || inputText;
        if (!textToRead) return;

        if (isSpeaking) {
            Speech.stop();
            setIsSpeaking(false);
            return;
        }

        setIsSpeaking(true);
        // iOS and Android will pick their default best voices for English. 
        // We slow the rate down slightly for dyslexia-friendliness.
        Speech.speak(textToRead, {
            language: 'en-US',
            pitch: 1.05,
            rate: 0.85,
            onDone: () => setIsSpeaking(false),
            onStopped: () => setIsSpeaking(false),
            onError: (e) => {
                console.error('Speech error', e);
                setIsSpeaking(false);
            }
        });
    };

    return (
        <SafeAreaView style={styles(theme).container} edges={['top', 'bottom']}>
            <Navbar />
            <ScrollView contentContainerStyle={styles(theme).content}>

                <View style={styles(theme).header}>
                    <Text style={styles(theme).welcomeText}>Welcome Back, Learner</Text>
                    <Text style={styles(theme).subtitleText}>Paste your notes below to make them easier to read.</Text>
                </View>

                {/* Quick Word Lab Stub */}
                <BentoCard
                    glowColor={theme.colors.primary}
                    onPress={() => router.push('/word-lab' as any)}
                >
                    <View style={styles(theme).bentoHeader}>
                        <View style={[styles(theme).iconBox, { backgroundColor: theme.colors.primary + '20' }]}>
                            <Sparkles color={theme.colors.primary} size={24} />
                        </View>
                        <View style={styles(theme).bentoHeaderText}>
                            <Text style={styles(theme).bentoTitle}>Quick Word Lab</Text>
                            <Text style={styles(theme).bentoSubtitle}>Type one word to see its rhythm & syllables.</Text>
                        </View>
                    </View>
                    <View style={styles(theme).wordLabInputArea}>
                        <TextInput
                            style={styles(theme).wordLabInput}
                            placeholder="e.g. Beautiful, Rhythm..."
                            placeholderTextColor={theme.colors.textSecondary}
                        />
                        <TouchableOpacity style={styles(theme).wordLabBtn}>
                            <Text style={styles(theme).wordLabBtnText}>Explore ΓåÆ</Text>
                        </TouchableOpacity>
                    </View>
                </BentoCard>

                {/* Input Area */}
                <View style={styles(theme).inputArea}>
                    <TextInput
                        style={styles(theme).textArea}
                        multiline
                        value={inputText}
                        onChangeText={setInputText}
                        placeholder="Paste difficult text or notes here..."
                        placeholderTextColor={theme.colors.textSecondary}
                        textAlignVertical="top"
                    />

                    <View style={styles(theme).actionButtonsRow}>
                        <TouchableOpacity
                            style={styles(theme).secondaryBtn}
                            onPress={handleAnalyze}
                            disabled={loadingType !== null || !inputText.trim()}
                        >
                            {loadingType === 'analyze' ? (
                                <ActivityIndicator size="small" color={theme.colors.textPrimary} />
                            ) : (
                                <Text style={styles(theme).secondaryBtnText}>Analyze</Text>
                            )}
                        </TouchableOpacity>
                        <TouchableOpacity
                            style={[styles(theme).primaryBtn, (!inputText.trim() || loadingType !== null) && styles(theme).btnDisabled]}
                            onPress={handleSimplify}
                            disabled={loadingType !== null || !inputText.trim()}
                        >
                            {loadingType === 'simplify' ? (
                                <ActivityIndicator size="small" color={theme.colors.white} />
                            ) : (
                                <Text style={styles(theme).primaryBtnText}>Simplify Text</Text>
                            )}
                        </TouchableOpacity>
                    </View>
                </View>

                {error ? (
                    <View style={styles(theme).errorBox}>
                        <Text style={styles(theme).errorText}>{error}</Text>
                    </View>
                ) : null}

                {/* Results Section */}
                {(simplifiedText || analysis) ? (
                    <View style={styles(theme).resultsSection}>
                        {simplifiedText ? (
                            <BentoCard glowColor={theme.colors.primary}>
                                <View style={styles(theme).resultHeader}>
                                    <Text style={[styles(theme).resultTitle, { color: theme.colors.primary }]}>Simplified Version</Text>

                                    <TouchableOpacity
                                        style={[styles(theme).ttsBtn, isSpeaking && styles(theme).ttsBtnActive]}
                                        onPress={handleReadAloud}
                                    >
                                        {isSpeaking ? (
                                            <Square color={theme.colors.white} size={16} fill={theme.colors.white} />
                                        ) : (
                                            <Volume2 color={theme.colors.primary} size={16} />
                                        )}
                                        <Text style={[styles(theme).ttsBtnText, isSpeaking && styles(theme).ttsBtnTextActive]}>
                                            {isSpeaking ? 'Stop Reading' : 'Read Aloud'}
                                        </Text>
                                    </TouchableOpacity>
                                </View>
                                <Text style={styles(theme).resultContent}>{simplifiedText}</Text>
                            </BentoCard>
                        ) : null}

                        {analysis ? (
                            <BentoCard glowColor="#3B82F6">
                                <Text style={[styles(theme).resultTitle, { color: '#3B82F6', marginBottom: theme.spacing.sm }]}>AI Analysis</Text>
                                <Text style={styles(theme).resultContent}>{analysis}</Text>
                            </BentoCard>
                        ) : null}
                    </View>
                ) : null}

                {/* Quick Tools */}
                <View style={styles(theme).quickToolsSection}>
                    <Text style={styles(theme).sectionHeading}>THIS MONTH'S PROGRESS</Text>
                    <ProgressCalendar />
                </View>

                <View style={styles(theme).quickToolsSection}>
                    <Text style={styles(theme).sectionHeading}>QUICK TOOLS</Text>
                    <View style={styles(theme).toolsGrid}>
                        <BentoCard
                            glowColor={theme.colors.primary}
                            style={styles(theme).toolCard}
                            onPress={() => router.push('/upload' as any)}
                        >
                            <View style={[styles(theme).iconBox, { backgroundColor: theme.colors.primary + '15', marginBottom: theme.spacing.sm }]}>
                                <FileText color={theme.colors.primary} size={24} />
                            </View>
                            <Text style={styles(theme).toolTitle}>Upload Worksheet</Text>
                            <Text style={styles(theme).toolSubtitle}>Convert PDFs to easy text</Text>
                        </BentoCard>

                        <BentoCard
                            glowColor="#3B82F6"
                            style={styles(theme).toolCard}
                            onPress={() => router.push('/stories' as any)}
                        >
                            <View style={[styles(theme).iconBox, { backgroundColor: '#3B82F615', marginBottom: theme.spacing.sm }]}>
                                <BookOpen color="#3B82F6" size={24} />
                            </View>
                            <Text style={styles(theme).toolTitle}>Practice Stories</Text>
                            <Text style={styles(theme).toolSubtitle}>Browse our story library</Text>
                        </BentoCard>
                    </View>
                </View>

            </ScrollView>
        </SafeAreaView>
    );
}

const styles = (theme: any) => StyleSheet.create({
    container: {
        flex: 1,
        backgroundColor: theme.colors.background,
    },
    content: {
        padding: theme.spacing.lg,
        paddingTop: theme.spacing.xl * 2,
        paddingBottom: 40,
    },
    header: {
        marginBottom: theme.spacing.lg,
    },
    welcomeText: {
        ...theme.typography.h1,
    },
    subtitleText: {
        ...theme.typography.body,
        marginTop: 4,
    },
    bentoHeader: {
        flexDirection: 'row',
        alignItems: 'center',
        marginBottom: theme.spacing.md,
    },
    iconBox: {
        width: 48,
        height: 48,
        borderRadius: theme.borderRadius.sm,
        justifyContent: 'center',
        alignItems: 'center',
        marginRight: theme.spacing.md,
    },
    bentoHeaderText: {
        flex: 1,
    },
    bentoTitle: {
        ...theme.typography.h2,
    },
    bentoSubtitle: {
        ...theme.typography.caption,
    },
    wordLabInputArea: {
        flexDirection: 'row',
        gap: theme.spacing.sm,
    },
    wordLabInput: {
        flex: 1,
        backgroundColor: '#F5F5F5',
        borderRadius: theme.borderRadius.md,
        paddingHorizontal: theme.spacing.md,
        fontSize: 16,
        ...theme.typography.body,
    },
    wordLabBtn: {
        backgroundColor: theme.colors.primary,
        paddingHorizontal: theme.spacing.lg,
        paddingVertical: theme.spacing.sm,
        justifyContent: 'center',
        borderRadius: theme.borderRadius.md,
    },
    wordLabBtnText: {
        ...theme.typography.body,
        color: theme.colors.white,
    },
    inputArea: {
        marginTop: theme.spacing.lg,
        position: 'relative',
    },
    textArea: {
        backgroundColor: theme.colors.white,
        height: 200,
        borderRadius: theme.borderRadius.lg,
        padding: theme.spacing.lg,
        paddingBottom: 64, // Space for buttons
        ...theme.typography.body,
        fontSize: 16,
        borderWidth: 1,
        borderColor: theme.colors.border,
    },
    actionButtonsRow: {
        position: 'absolute',
        bottom: theme.spacing.md,
        right: theme.spacing.md,
        flexDirection: 'row',
        gap: theme.spacing.sm,
    },
    primaryBtn: {
        backgroundColor: theme.colors.primary,
        paddingHorizontal: theme.spacing.lg,
        paddingVertical: theme.spacing.sm,
        borderRadius: 9999,
        shadowColor: theme.colors.primary,
        shadowOffset: { width: 0, height: 2 },
        shadowOpacity: 0.3,
        shadowRadius: 4,
        elevation: 3,
    },
    primaryBtnText: {
        ...theme.typography.body,
        color: theme.colors.white,
    },
    secondaryBtn: {
        backgroundColor: '#F5F5F5',
        paddingHorizontal: theme.spacing.md,
        paddingVertical: theme.spacing.sm,
        borderRadius: 9999,
    },
    secondaryBtnText: {
        ...theme.typography.body,
        fontSize: 14,
    },
    btnDisabled: {
        opacity: 0.6,
    },
    errorBox: {
        backgroundColor: '#FEE2E2',
        borderWidth: 1,
        borderColor: '#FCA5A5',
        padding: theme.spacing.md,
        borderRadius: theme.borderRadius.md,
        marginTop: theme.spacing.md,
    },
    errorText: {
        ...theme.typography.caption,
        color: '#EF4444',
    },
    resultsSection: {
        marginTop: theme.spacing.xl,
        gap: theme.spacing.md,
    },
    resultHeader: {
        flexDirection: 'row',
        justifyContent: 'space-between',
        alignItems: 'center',
        marginBottom: theme.spacing.sm,
    },
    resultTitle: {
        ...theme.typography.h2,
        fontSize: 18,
    },
    ttsBtn: {
        flexDirection: 'row',
        alignItems: 'center',
        gap: 6,
        backgroundColor: theme.colors.primary + '15',
        paddingHorizontal: 12,
        paddingVertical: 6,
        borderRadius: 9999,
    },
    ttsBtnActive: {
        backgroundColor: '#EF4444',
    },
    ttsBtnText: {
        ...theme.typography.body,
        color: theme.colors.primary,
        fontSize: 12,
    },
    ttsBtnTextActive: {
        color: theme.colors.white,
    },
    resultContent: {
        ...theme.typography.body,
        fontSize: 18,
        lineHeight: 28,
        color: theme.colors.textPrimary,
    },
    quickToolsSection: {
        marginTop: theme.spacing.xl,
    },
    sectionHeading: {
        ...theme.typography.caption,
        fontSize: 12,
        marginBottom: theme.spacing.md,
        marginLeft: 4,
    },
    toolsGrid: {
        flexDirection: 'row',
        gap: theme.spacing.md,
    },
    toolCard: {
        flex: 1,
    },
    toolTitle: {
        ...theme.typography.body,
        fontSize: 14,
    },
    toolSubtitle: {
        ...theme.typography.caption,
        fontSize: 12,
        marginTop: 2,
    }
});

import { Href, usePathname, useRouter } from 'expo-router';
import { BarChart2, Home, Moon, UploadCloud } from 'lucide-react-native';
import React from 'react';
import { StyleSheet, Text, TouchableOpacity, View } from 'react-native';
import { useTheme } from '../context/ThemeContext';

export const Navbar = ({ activeTab = 'home', onTabChange }: { activeTab?: 'home' | 'features', onTabChange?: (tab: 'home' | 'features') => void }) => {
    const { theme, isDark, toggleTheme } = useTheme();
    const router = useRouter();
    const pathname = usePathname();

    // Derived active tab based on route if not controlled
    const isStats = pathname === '/stats';
    const isUpload = pathname === '/upload';
    const isHome = pathname === '/' && activeTab === 'home';
    const isFeatures = pathname === '/' && activeTab === 'features';
    return (
        <View style={styles(theme).container}>
            {/* Brand */}
            <View style={styles(theme).brand}>
                <Text style={styles(theme).logoText}>DYSCOVER</Text>
                <Text style={styles(theme).subtitle}>INCLUSIVE SUPPORT</Text>
            </View>

            {/* Nav Actions (Simulated Dock) */}
            <View style={styles(theme).actions}>
                <TouchableOpacity
                    style={[styles(theme).iconBtn, isHome && styles(theme).activeBtn]}
                    onPress={() => {
                        if (pathname !== '/') router.push('/');
                        else onTabChange?.('home');
                    }}
                >
                    <Home color={isHome ? theme.colors.primary : theme.colors.textSecondary} size={20} />
                </TouchableOpacity>
                <TouchableOpacity
                    style={[styles(theme).iconBtn, isUpload && styles(theme).activeBtn]}
                    onPress={() => router.push('/upload' as Href)}
                >
                    <UploadCloud color={isUpload ? theme.colors.primary : theme.colors.textSecondary} size={20} />
                </TouchableOpacity>
                <TouchableOpacity
                    style={[styles(theme).iconBtn, isStats && styles(theme).activeBtn]}
                    onPress={() => router.push('/stats' as Href)}
                >
                    <BarChart2 color={isStats ? theme.colors.primary : theme.colors.textSecondary} size={20} />
                </TouchableOpacity>

                <TouchableOpacity style={styles(theme).iconBtn} onPress={toggleTheme}>
                    <Moon color={isDark ? theme.colors.primary : theme.colors.textSecondary} size={20} />
                </TouchableOpacity>
                <TouchableOpacity style={styles(theme).avatarBtn} onPress={() => router.push('/profile' as Href)}>
                    <Text style={styles(theme).avatarText}>L</Text>
                </TouchableOpacity>
            </View>
        </View>
    );
};

const styles = (theme: any) => StyleSheet.create({
    container: {
        flexDirection: 'row',
        alignItems: 'center',
        justifyContent: 'space-between',
        paddingHorizontal: theme.spacing.lg,
        paddingVertical: theme.spacing.md,
        backgroundColor: theme.colors.white,
        borderBottomWidth: 1,
        borderBottomColor: theme.colors.border,
        zIndex: 50,
    },
    brand: {
        flexDirection: 'column',
    },
    logoText: {
        ...theme.typography.h1,
        fontSize: 20,
        letterSpacing: 0,
    },
    subtitle: {
        ...theme.typography.caption,
        fontSize: 10,
        letterSpacing: 2,
        color: theme.colors.textSecondary,
    },
    actions: {
        flexDirection: 'row',
        alignItems: 'center',
        gap: theme.spacing.sm,
    },
    iconBtn: {
        width: 40,
        height: 40,
        borderRadius: theme.borderRadius.md,
        justifyContent: 'center',
        alignItems: 'center',
    },
    activeBtn: {
        backgroundColor: theme.colors.primary + '20',
    },
    avatarBtn: {
        width: 36,
        height: 36,
        borderRadius: theme.borderRadius.circle,
        backgroundColor: theme.colors.primary,
        justifyContent: 'center',
        alignItems: 'center',
        marginLeft: theme.spacing.xs,
    },
    avatarText: {
        color: theme.colors.white,
        fontWeight: 'bold',
        fontSize: 14,
    }
});
